<script>(()=>{const tabs=[...document.querySelectorAll('[data-tab]')],panels=[...document.querySelectorAll('[data-tab-panel]')],storageKey=`portfolio-tab:${location.pathname}`;const open=id=>{if(!panels.some(panel=>panel.id===id))id='profile';tabs.forEach(tab=>{const active=tab.dataset.tab===id;tab.classList.toggle('active',active);tab.setAttribute('aria-selected',active?'true':'false')});panels.forEach(panel=>panel.classList.toggle('active',panel.id===id));sessionStorage.setItem(storageKey,id);history.replaceState(null,'','#'+id)};tabs.forEach(tab=>tab.addEventListener('click',()=>open(tab.dataset.tab)));open(location.hash.slice(1)||sessionStorage.getItem(storageKey)||'profile')})()</script>
<script>(()=>{if(new URLSearchParams(location.search).get('focus')!=='about')return;requestAnimationFrame(()=>{const field=document.querySelector('#about-business textarea');if(!field)return;field.scrollIntoView({behavior:'smooth',block:'center'});field.focus({preventScroll:true})})})()</script>
<script>(()=>{const setOpen=(id,open)=>{const box=document.getElementById(id),button=document.querySelector(`.offering-edit-toggle[data-target="${id}"]`);if(!box)return;box.hidden=!open;if(button){button.setAttribute('aria-expanded',open?'true':'false');button.textContent=open?'Close':'Edit'}if(open)box.querySelector('input[name="title"]')?.focus()};document.querySelectorAll('.offering-edit-toggle').forEach(button=>button.addEventListener('click',()=>{const box=document.getElementById(button.dataset.target);setOpen(button.dataset.target,box?.hidden??true)}));document.querySelectorAll('.offering-edit-cancel').forEach(button=>button.addEventListener('click',()=>setOpen(button.dataset.target,false)))})()</script>
<script>(()=>{const search=document.getElementById('category-search'),box=document.getElementById('category-options'),count=document.getElementById('category-count'),help=document.getElementById('category-limit');if(!search||!box)return;const options=[...box.querySelectorAll('.category-option')],checks=options.map(option=>option.querySelector('input[type="checkbox"]'));const refresh=()=>{const selected=checks.filter(check=>check.checked).length;count.textContent=`${selected} / 3 selected`;help.classList.toggle('at-limit',selected>=3);checks.forEach(check=>{const disabled=!check.checked&&selected>=3;check.disabled=disabled;check.closest('.category-option').classList.toggle('is-disabled',disabled)});};search.addEventListener('input',()=>{const query=search.value.trim().toLowerCase();options.forEach(option=>option.hidden=!option.textContent.toLowerCase().includes(query))});checks.forEach(check=>check.addEventListener('change',refresh));refresh()})()</script></body></html>
